import { create } from "zustand";

export type ThemeMode = "light" | "dark" | "auto";
export type ResolvedTheme = "light" | "dark";

const STORAGE_KEY = "rp_theme";

function resolveTheme(mode: ThemeMode): ResolvedTheme {
  if (mode === "auto") {
    try {
      return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    } catch {
      // ignore
    }
    return "light";
  }
  return mode;
}

function applyTheme(resolved: ResolvedTheme) {
  const el = document.documentElement;
  if (resolved === "dark") {
    el.classList.add("dark");
  } else {
    el.classList.remove("dark");
  }
  el.dataset.theme = resolved;
}

type ThemeState = {
  mode: ThemeMode;
  effective: ResolvedTheme;
  hydrated: boolean;
  setMode: (m: ThemeMode) => void;
  init: () => void;
};

export const useThemeStore = create<ThemeState>((set, get) => ({
  mode: "auto",
  effective: "light",
  hydrated: false,
  setMode: (m: ThemeMode) => {
    const effective = resolveTheme(m);
    applyTheme(effective);
    try {
      localStorage.setItem(STORAGE_KEY, m);
    } catch {
      // ignore
    }
    set({ mode: m, effective });
  },
  init: () => {
    if (get().hydrated) return;
    let mode: ThemeMode = "auto";
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored === "light" || stored === "dark" || stored === "auto") {
        mode = stored as ThemeMode;
      }
    } catch {
      // ignore
    }
    // index.html script already applied the class before React mounted — just sync state
    set({ mode, effective: resolveTheme(mode), hydrated: true });
  },
}));

export function useTheme() {
  const mode = useThemeStore((s) => s.mode);
  const effective = useThemeStore((s) => s.effective);
  const setMode = useThemeStore((s) => s.setMode);
  const init = useThemeStore((s) => s.init);
  const hydrated = useThemeStore((s) => s.hydrated);
  return { mode, effective, setMode, init, hydrated };
}
